def intake_incidents(csv_text):
    """Validate and clean a CSV string of incidents into a summary dict."""
    lines = []
    for line in csv_text.split("\n"):
        if line.strip() != "":
            lines.append(line)

    rows = []
    if len(lines) > 0:
        headers = []
        for header in lines[0].split(","):
            headers.append(header.strip())
        for line in lines[1:]:
            values = []
            for value in line.split(","):
                values.append(value.strip())
            row = {}
            for position in range(len(headers)):
                if position < len(values):
                    row[headers[position]] = values[position]
                else:
                    row[headers[position]] = ""
            rows.append(row)

    required = ["id", "branch", "system", "minutes_down", "day"]
    errors = []
    incidents = []
    rejected = 0

    for position in range(len(rows)):
        row = rows[position]
        row_number = position + 1
        row_errors = []
        for field in required:
            if str(row.get(field, "")).strip() == "":
                row_errors.append("Row " + str(row_number) + ": missing " + field)
        for field in ["minutes_down", "day"]:
            text = str(row.get(field, "")).strip()
            if text != "" and not text.isdigit():
                row_errors.append("Row " + str(row_number) + ": " + field + " must be a whole number")
        if len(row_errors) > 0:
            errors = errors + row_errors
            rejected = rejected + 1
        else:
            branch_words = []
            for word in row["branch"].split():
                branch_words.append(word.capitalize())
            incidents.append({
                "id": row["id"],
                "branch": " ".join(branch_words),
                "system": row["system"].lower(),
                "description": str(row.get("description", "")).strip(),
                "minutes_down": int(row["minutes_down"]),
                "day": int(row["day"]),
            })

    return {
        "accepted": len(incidents),
        "rejected": rejected,
        "errors": errors,
        "incidents": incidents,
    }

