def flag_candidate_problems(incidents, threshold):
    counts = {}
    for incident in incidents:
        key = incident["system"] + "|" + incident["branch"]
        if key in counts:
            counts[key] = counts[key] + 1
        else:
            counts[key] = 1
    flagged = []
    for key in counts:
        if counts[key] >= threshold:
            flagged.append(key)
    return sorted(flagged)

def count_in_window(incidents, system, branch, current_day, window_days):
    total = 0
    for incident in incidents:
        if incident["system"] != system:
            continue
        if incident["branch"] != branch:
            continue
        day = incident["day"]
        if day <= current_day and day > current_day - window_days:
            total = total + 1
    return total

def description_similarity(text_a, text_b):
    words_a = set(text_a.lower().split())
    words_b = set(text_b.lower().split())
    all_words = words_a | words_b
    if len(all_words) == 0:
        return 0.0
    shared = words_a & words_b
    return round(len(shared) / len(all_words), 2)

