def apply_override_rule(incidents, auto_assignments, pinned):
    result = []
    for incident in incidents:
        incident_id = incident["id"]
        if incident_id in pinned:
            result.append({"id": incident_id, "problem_id": pinned[incident_id], "source": "manual"})
        elif incident_id in auto_assignments:
            result.append({"id": incident_id, "problem_id": auto_assignments[incident_id], "source": "automatic"})
        else:
            result.append({"id": incident_id, "problem_id": None, "source": "unassigned"})
    return result

