def validate_form_presence(form):
    missing = []
    for field in ["branch", "system", "minutes_down"]:
        value = form.get(field)
        if value is None or (isinstance(value, str) and value.strip() == ""):
            missing.append(field)
    return missing

def validate_form(form):
    errors = []
    for field in ["branch", "system", "minutes_down"]:
        value = form.get(field)
        if value is None or (isinstance(value, str) and value.strip() == ""):
            errors.append(field + " is required")
    minutes_value = form.get("minutes_down")
    minutes_blank = minutes_value is None or (isinstance(minutes_value, str) and minutes_value.strip() == "")
    if not minutes_blank:
        try:
            number = float(minutes_value)
            if number < 0:
                errors.append("minutes_down must be a non-negative number")
        except (ValueError, TypeError):
            errors.append("minutes_down must be a non-negative number")
    return errors

def add_config_row(rows, new_row):
    existing_ids = [row.get("id") for row in rows]
    if new_row.get("id") in existing_ids:
        return list(rows)
    return rows + [new_row]

def update_config_row(rows, row_id, field, value):
    new_rows = []
    for row in rows:
        if row.get("id") == row_id:
            updated = dict(row)
            updated[field] = value
            new_rows.append(updated)
        else:
            new_rows.append(row)
    return new_rows
